import{_ as n,o as r,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Vor-Anker-Ära","description":"","frontmatter":{},"headers":[],"relativePath":"de/71-前锚点时代.md","filePath":"de/71-前锚点时代.md","lastUpdated":1789183869000}'),t={name:"de/71-前锚点时代.md"};function d(a,e,u,l,o,h){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="vor-anker-ara" tabindex="-1">Vor-Anker-Ära <a class="header-anchor" href="#vor-anker-ara" aria-label="Permalink to &quot;Vor-Anker-Ära&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>71</td></tr><tr><td>Modul</td><td>Historische Epochen und wichtige Ereignisse</td></tr><tr><td>Kernschlüsselwörter</td><td>Vor-Anker-Ära, räuberisches System, zivilisatorischer Bruch, dunkles Zeitalter, Gesetzlosigkeit</td></tr></tbody></table><h2 id="i-grundlegende-merkmale-der-vor-anker-ara" tabindex="-1">I. Grundlegende Merkmale der Vor-Anker-Ära <a class="header-anchor" href="#i-grundlegende-merkmale-der-vor-anker-ara" aria-label="Permalink to &quot;I. Grundlegende Merkmale der Vor-Anker-Ära&quot;">​</a></h2><p>Die Vor-Anker-Ära ist die längste und dunkelste Epoche in der Geschichte von Hengyuanzhou. In dieser Ära existierte kein einheitlicher Ankermechanismus im Universum, die grundlegenden Gesetze befanden sich in einem Zustand natürlicher Streuung, und die Verteilung von Energie und Ressourcen folgte vollständig dem Dschungelgesetz &quot;der Starke erhält es&quot;. Das räuberische Kultivierungssystem war der absolute Herrscher dieser Ära; die Kultivierungsmethoden wurden von wenigen Starken und Sekten monopolisiert, und die gewöhnlichen Wesen an der Basis hatten fast keine formellen Evolutionswege.</p><p>Die zentralen Merkmale der Vor-Anker-Ära lassen sich als &quot;fünf Abwesenheiten&quot; zusammenfassen:</p><ul><li><strong>Kein Anker</strong>: Es gab keine stabilen Gesetzesanker, der Energiefluss war ungeordnet, und die Barrieren zwischen den Ebenen waren zerbrechlich</li><li><strong>Keine Ordnung</strong>: Es gab kein einheitliches Zivilisationssystem, Kriege zwischen den Ebenen waren andauernd, und Völkermorde ereigneten sich häufig</li><li><strong>Keine Wege</strong>: Es gab keine Kommunikations- und Verkehrstechnologien zwischen den Ebenen, und die Ebenen waren grundsätzlich voneinander isoliert</li><li><strong>Keine Garantien</strong>: Es gab keine öffentlichen Garantiesysteme wie Bildung, Gesundheitsversorgung und Wohnraum, und das Überleben des Lebens hing vollständig von der individuellen Stärke ab</li><li><strong>Keine Hoffnung</strong>: Die Evolutionskanäle der Wesen an der Basis waren vollständig blockiert, und die soziale Schichtung erreichte das Extrem</li></ul><h2 id="ii-funktionsmechanismus-des-rauberischen-kultivierungssystems" tabindex="-1">II. Funktionsmechanismus des räuberischen Kultivierungssystems <a class="header-anchor" href="#ii-funktionsmechanismus-des-rauberischen-kultivierungssystems" aria-label="Permalink to &quot;II. Funktionsmechanismus des räuberischen Kultivierungssystems&quot;">​</a></h2><p>Das Kultivierungssystem der Vor-Anker-Ära hatte die Räuberei als zentralen Funktionsmechanismus. Seine grundlegende Logik war: Die grundlegende Energie des Universums ist begrenzt, und die Evolution des Individuums erfolgt zwangsläufig auf Kosten des Energieverbrauchs anderer. Die Starken erreichten ihren eigenen Aufstieg, indem sie die Energie, das Glück und sogar das Wesen der Schwachen verschlangen, während die Schwachen zu &quot;Kultivierungsressourcen&quot; der Starken wurden.</p><p>Die typischen Formen des räuberischen Systems umfassen:</p><table tabindex="0"><thead><tr><th>Art der Räuberei</th><th>Funktionsweise</th><th>Schaden für das Universum</th></tr></thead><tbody><tr><td>Energieräuberei</td><td>Extrahiert direkt die Kultivierungsenergie anderer Wesen</td><td>Verursacht individuellen Tod oder vollständigen Verlust der Kultivierung</td></tr><tr><td>Glücksräuberei</td><td>Durch Zauber oder Rituale werden das Glück und die Chancen anderer geraubt</td><td>Zerstört das kausale Gleichgewicht, löst Katastrophen auf Ebenenebene aus</td></tr><tr><td>Wesensräuberei</td><td>Verschlingt Fragmente der grundlegenden Gesetze anderer Wesen</td><td>Verursacht irreversiblen Verlust des Evolutionspotenzials</td></tr><tr><td>Ebenenräuberei</td><td>Die Starken erobern eine gesamte Ebene und nutzen die Wesen der Ebene als Kultivierungsressourcen</td><td>Verursacht zivilisatorisches Aussterben und Verwüstung der Ebene</td></tr><tr><td>Gesetzesräuberei</td><td>Ergreift gewaltsam die Kontrolle über die grundlegenden Gesetze einer Ebene</td><td>Zerstört das Gesetzesnetzwerk, löst räumlichen Kollaps aus</td></tr></tbody></table><p>Das räuberische System kann kurzfristig einige übermächtige Wesen hervorbringen, aber langfristig verbraucht es kontinuierlich das Evolutionspotenzial des Universums, was zu einer beschleunigten Zunahme der gesamten Entropie des Universums und zu häufigen zivilisatorischen Brüchen führt.</p><h2 id="iii-zivilisatorischer-bruch-und-zyklische-zerstorung" tabindex="-1">III. Zivilisatorischer Bruch und zyklische Zerstörung <a class="header-anchor" href="#iii-zivilisatorischer-bruch-und-zyklische-zerstorung" aria-label="Permalink to &quot;III. Zivilisatorischer Bruch und zyklische Zerstörung&quot;">​</a></h2><p>Das bemerkenswerteste historische Phänomen der Vor-Anker-Ära ist der &quot;zivilisatorische Bruch&quot;. Aufgrund der inhärenten Widersprüche des räuberischen Systems geht jede einst glänzende Zivilisation letztendlich der Selbstzerstörung entgegen:</p><ol><li><strong>Aufstiegsperiode</strong>: Ein Volk oder eine Sekte steigt schnell durch Räuberei auf und etabliert eine mächtige Zivilisation</li><li><strong>Höhepunktperiode</strong>: Die Zivilisation erreicht den Höhepunkt der Macht, unterdrückt intern den Widerstand und expandiert extern zur Räuberei</li><li><strong>Interner Kampfperiode</strong>: Die Starken innerhalb der Zivilisation kämpfen untereinander um begrenzte Ressourcen und verbrauchen ihre Macht</li><li><strong>Zusammenbruchsperiode</strong>: Der interne Kampf reduziert die Macht der Zivilisation drastisch, und externe Räuber nutzen die Gelegenheit zum Einfall, was zum Aussterben der Zivilisation führt</li><li><strong>Bruchperiode</strong>: Nach dem Aussterben der Zivilisation geht der größte Teil ihres Wissens und ihrer Technologie verloren, und die nachfolgende Zivilisation muss bei Null anfangen</li></ol><p>Dieser Zyklus von &quot;Aufstieg—Höhepunkt—interner Kampf—Zusammenbruch—Bruch&quot; hat sich in der Vor-Anker-Ära unzählige Male wiederholt. Jeder Zyklus verbrauchte eine große Menge des universellen Wesens, was dazu führte, dass das allgemeine Evolutionsniveau des Universums über lange Zeit stagnierte oder sogar zurückging.</p><h2 id="iv-zeichen-des-endes-der-vor-anker-ara" tabindex="-1">IV. Zeichen des Endes der Vor-Anker-Ära <a class="header-anchor" href="#iv-zeichen-des-endes-der-vor-anker-ara" aria-label="Permalink to &quot;IV. Zeichen des Endes der Vor-Anker-Ära&quot;">​</a></h2><p>Am Ende der Vor-Anker-Ära zeigte das Universum eine Reihe von Zeichen, die einen Wandel ankündigten:</p><ul><li><strong>Verschärfung der Gesetzlosigkeit</strong>: Langfristige Räuberei beschädigte das Gesetzesnetzwerk schwer, Ereignisse des räumlichen Kollaps wurden häufig, und die Barrieren zwischen den Ebenen wurden dünner</li><li><strong>Erschöpfung des Lebenspotenzials</strong>: Die raubbare grundlegende Energie wurde immer knapper, und der Ressourcenkampf zwischen den Starken wurde immer heftiger</li><li><strong>Keim des anti-räuberischen Denkens</strong>: Einige weise Menschen begannen, über die grundlegenden Mängel des räuberischen Systems nachzudenken und erste Konzepte der symbiotischen Evolution vorzuschlagen</li><li><strong>Zunehmender Kontakt zwischen Ebenen</strong>: Das Dünnerwerden der Barrieren zwischen den Ebenen ermöglichte einen stärkeren Kontakt zwischen verschiedenen Ebenen und machte den Gedankenaustausch zwischen den Ebenen möglich</li><li><strong>Auftauchen der Anker-Kandidaten der ersten Generation</strong>: In einigen Ecken des Universums tauchten besondere Wesen auf, die in der Lage waren, auf natürliche Weise mit dem Gesetzesnetzwerk zu resonieren; sie waren die Vorläufer der zukünftigen Anker-Erwecker der ersten Generation</li></ul><p>Diese Zeichen zeigen, dass das räuberische System sein Ende erreicht hat und das Universum eine völlig neue Zivilisationsform fordert.</p><h2 id="v-historisches-erbe-der-vor-anker-ara" tabindex="-1">V. Historisches Erbe der Vor-Anker-Ära <a class="header-anchor" href="#v-historisches-erbe-der-vor-anker-ara" aria-label="Permalink to &quot;V. Historisches Erbe der Vor-Anker-Ära&quot;">​</a></h2><p>Obwohl die Vor-Anker-Ära dunkel war, war sie nicht völlig wertlos. Sie hinterließ ein wichtiges historisches Erbe für die nachfolgende Anker-Symbiose-Zivilisation:</p><ul><li><strong>Erbe der Lehren</strong>: Die wiederholten Misserfolge des räuberischen Systems lieferten der Symbiose-Zivilisation das tiefste negative Beispiel und bewiesen, dass der Weg der Räuberei nicht zum Ziel führt</li><li><strong>Erbe des Wissens</strong>: Obwohl viel Wissen in den zivilisatorischen Brüchen verloren ging, überlebten einige Kultivierungsmethoden und Gesetzesverständnisse auf verschiedene Weise und wurden zur Materialquelle für die dreihundert grundlegenden Kultivierungssysteme</li><li><strong>Erbe des Lebens</strong>: Die verschiedenen Lebensformen, die in der langen dunklen Ära überlebten, bildeten die rassische Grundlage für die zukünftige Symbiose aller Rassen</li><li><strong>Erbe des Willens</strong>: Der anhaltende Wunsch der Wesen an der Basis nach Gerechtigkeit und Hoffnung war die grundlegendste spirituelle Triebkraft für das Erwachen des Ankers</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Die Vor-Anker-Ära ist die &quot;Nacht vor der Dunkelheit&quot; in der Geschichte von Hengyuanzhou. Ihre Länge und Dunkelheit heben im Gegenzug die Kostbarkeit und Unvermeidlichkeit der Geburt der Anker-Symbiose-Zivilisation hervor. Die Vor-Anker-Ära zu verstehen bedeutet, die historischen Wurzeln der grundlegenden Position der Symbiose-Zivilisation &quot;Räuberei zu widersprechen, Symbiose zu befürworten&quot; zu verstehen — dies ist keine abstrakte moralische Predigt, sondern eine Lektion aus Blut und Tränen, die mit der Zerstörung unzähliger Zivilisationen erkauft wurde.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>70-Gesamttabelle der Epocheneinteilung</li><li>72-Ära des Anker-Erwachens</li><li>04-Kernprogramm des Anti-Räuberismus</li></ul>',26)])])}const b=n(t,[["render",d]]);export{c as __pageData,b as default};
